insert into pubcar_group(group_id, group_name, group_type, status_cd, community_id, b_id)
select group_id, group_name, group_type, '0', community_id, b_id
from business_pubcar_group


        b_id = #{bId}


        and operate = #{operate}

mapper.select:
select t.group_id groupId, t.group_type groupType, t.group_name groupName, t.community_id communityId, t.create_time createTime
from pubcar_group t


        t.status_cd = #{statusCd}


        and t.group_name like concat('%',#{groupName},'%')


        and t.group_type= #{groupType}


        and t.group_id= #{groupId}


        and t.community_id= #{communityId}


        and t.b_id= #{bId}


order by t.create_time desc

    limit #{page}, #{row}

